\resultentry{003}{The quasi-Riemann hypothesis}{Proves that every Dirichlet $L$-function, including $\zeta(s)$, is zero-free in $\Re s>7/8$, resolving the quasi-Riemann hypothesis. The same half-plane is zero-free for every finite-order Hecke $L$-function over $\mathbb Q(\sqrt{-3})$. A companion gives a different proof of the zero-free half-plane $\Re s>11/12$.}{\href{https://github.com/openai/math/blob/main/preprints/The-Quasi-Riemann-Hypothesis-September-30-2026/paper.pdf}{The Quasi-Riemann Hypothesis: A Zero-Free Half-Plane $\Re s>7/8$}\enspace\textperiodcentered\enspace\href{https://github.com/openai/math/blob/main/preprints/The-Quasi-Riemann-Hypothesis-October-5-2026/paper2.pdf}{The Quasi-Riemann Hypothesis (alternate $11/12$ proof)}\enspace\textperiodcentered\enspace\href{https://github.com/openai/math/blob/main/preprints/Uniform-exclusion-of-Landau-Siegel-zeros-October-1-2026/paper.pdf}{Uniform exclusion of Landau--Siegel zeros}}

\cataloguesection{Number theory}{1}
\resultentry{017}{The irrationality exponent of $\pi$ is $2$}{Proves that the irrationality exponent of $\pi$ is exactly $2$: for every $\varepsilon>0$ and all sufficiently large denominators $q$, every rational $p/q$ satisfies $|\pi-p/q|\ge q^{-2-\varepsilon}$. This also proves convergence of the Flint--Hills series $\sum_{n\ge1}1/(n^3\sin^2 n)$, with angles in radians.}{\href{https://github.com/openai/math/blob/main/preprints/The-irrationality-exponent-of-pi-is-2-September-24-2026/paper.pdf}{The irrationality exponent of pi is 2}}

\cataloguesection{Algebra}{2}
\resultentry{195}{A counterexample to the small Cohen--Macaulay module conjecture}{Constructs a three-dimensional complete Noetherian normal local domain over $\mathbb C$ with no nonzero finitely generated maximal Cohen--Macaulay module. A three-dimensional local domain essentially of finite type over $\mathbb C$ has the same property, disproving the domain form of the small Cohen--Macaulay module conjecture.}{\href{https://github.com/openai/math/blob/main/preprints/A-Complete-Local-Domain-Without-a-Small-Cohen-Macaulay-Module-September-23-2026/paper.pdf}{A Complete Local Domain without a Small Cohen–Macaulay Module}}

\cataloguesection{Probability and statistical mechanics}{15}
\resultentry{223}{Conformal limits of square-lattice random-cluster interfaces}{Proves chordal $\mathrm{SLE}_\kappa$ limits for critical square-lattice random-cluster interfaces for $0<q\le4$, with $\kappa=4\pi/\arccos(-\sqrt q/2)$: bounded Jordan domains are allowed for $q\ge1$, and smooth Jordan domains for $q<1$, under the stated marked-boundary approximations. For $1\le q\le4$, complete nested plane loops converge to $\mathrm{CLE}_\kappa$.}{\href{https://github.com/openai/math/blob/main/preprints/Square-lattice-FK-interfaces-and-nested-loops-for-1-leq-q-lt-4-September-23-2026/paper.pdf}{FK interfaces and nested loops ($1\le q<4$)}\enspace\textperiodcentered\enspace\href{https://github.com/openai/math/blob/main/preprints/Self-dual-random-cluster-interfaces-below-one-September-23-2026/paper.pdf}{Self-dual interfaces ($q<1$)}\enspace\textperiodcentered\enspace\href{https://github.com/openai/math/blob/main/preprints/Quenched-SLE-Universality-for-Weakly-Disordered-FK-Ising-Interfaces-October-5-2026/quenched-fk-ising.pdf}{Quenched SLE Universality for Weakly Disordered FK--Ising Interfaces}\enspace\textperiodcentered\enspace\href{https://github.com/openai/math/blob/main/preprints/Thermal-FK-Ising-interfaces-and-massive-SLE-October-5-2026/paper.pdf}{Thermal FK--Ising interfaces and massive SLE}\enspace\textperiodcentered\enspace\href{https://github.com/openai/math/blob/main/preprints/Natural-Occupation-Measures-for-Critical-Square-Lattice-FK-Interfaces-October-5-2026/natural-occupation-measures-critical-square-lattice-fk-interfaces.pdf}{Natural Occupation Measures for Critical Square-Lattice FK Interfaces}\enspace\textperiodcentered\enspace\href{https://github.com/openai/math/blob/main/preprints/Conformal-Limits-of-Critical-Square-Lattice-Random-Cluster-Interfaces-October-5-2026/paper.pdf}{Conformal Limits of Critical Square-Lattice Random-Cluster Interfaces}}

